const NAMES = ['Alice Johnson', 'Boris Petrov', 'Carol Nguyen', 'David Okafor'];

test('filterNames matches regardless of case', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'alice'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(NAMES, 'ALICE'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(NAMES, 'AlIcE'), ['Alice Johnson']);
});

test('filterNames matches anywhere in the name, not just the start', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'petrov'), ['Boris Petrov']);
  assert.deepStrictEqual(filterNames(NAMES, 'o'), NAMES);
});

test('filterNames keeps every name for an empty or whitespace query', () => {
  assert.deepStrictEqual(filterNames(NAMES, ''), NAMES);
  assert.deepStrictEqual(filterNames(NAMES, '   '), NAMES);
});

test('filterNames ignores whitespace around the query', () => {
  assert.deepStrictEqual(filterNames(NAMES, '  carol  '), ['Carol Nguyen']);
});

test('filterNames returns nothing when no name matches', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'zzz'), []);
});

test('filterNames can match several names at once', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'o j'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(NAMES, 'ov'), ['Boris Petrov']);
});

test('filterNames does not mutate or alias the input array', () => {
  const input = NAMES.slice();
  const out = filterNames(input, '');
  out.push('Mallory');
  assert.deepStrictEqual(input, NAMES);
});

